"""Small editable UI vectors; no raster artwork is generated by this script."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2] / 'assets/school/r2'
ROOT.mkdir(parents=True, exist_ok=True)

def svg(name, w, h, content):
    (ROOT/name).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{content}</svg>', encoding='utf-8')

defs='''<defs><linearGradient id="gold" x2="0" y2="1"><stop stop-color="#ffe4a0"/><stop offset=".42" stop-color="#ac632a"/><stop offset=".7" stop-color="#f1c675"/><stop offset="1" stop-color="#713c1d"/></linearGradient><linearGradient id="paper" x2="0" y2="1"><stop stop-color="#fff5da"/><stop offset=".55" stop-color="#ffe9bf"/><stop offset="1" stop-color="#e4c08c"/></linearGradient><linearGradient id="green" x2="0" y2="1"><stop stop-color="#395c2e"/><stop offset=".55" stop-color="#26492e"/><stop offset="1" stop-color="#19341e"/></linearGradient></defs>'''
for name, fill in [('pill_cream.svg','paper'),('primary_green.svg','green'),('hud_frame.svg','paper')]:
    leaf='''<g fill="none" stroke="#c38d43" stroke-width="2.5" opacity=".9"><path d="M40 68 Q60 65 76 39 M47 61 Q36 47 43 44 Q52 48 51 57 M56 53 Q47 37 55 35 Q62 40 61 47 M65 45 Q61 29 69 29 Q77 33 70 39"/><path d="M600 68 Q580 65 564 39 M593 61 Q604 47 597 44 Q588 48 589 57 M584 53 Q593 37 585 35 Q578 40 579 47 M575 45 Q579 29 571 29 Q563 33 570 39"/></g>'''
    svg(name,640,110,defs+f'<rect x="5" y="9" width="630" height="97" rx="46" fill="#482818" opacity=".4"/><rect x="4" y="3" width="632" height="98" rx="46" fill="url(#gold)" stroke="#613418" stroke-width="2"/><rect x="10" y="9" width="620" height="86" rx="40" fill="url(#{fill})" stroke="#fff1bc" stroke-width="2"/><rect x="16" y="15" width="608" height="74" rx="35" fill="none" stroke="#a4612c" stroke-width="1.5"/>'+leaf)

for name, fill in [('mode_paper.svg','paper'),('mode_green.svg','green')]:
    svg(name,300,170,defs+f'<rect x="5" y="9" width="290" height="156" rx="22" fill="#5b371f" opacity=".35"/><rect x="4" y="4" width="292" height="155" rx="22" fill="url(#gold)" stroke="#f8db9e" stroke-width="2"/><rect x="10" y="10" width="280" height="143" rx="17" fill="url(#{fill})" stroke="#8c4c25" stroke-width="2"/><rect x="15" y="15" width="270" height="133" rx="14" fill="none" stroke="#f5cf8a" stroke-width="1"/>')

svg('speech_bubble.svg',400,210,defs+'<path d="M25 25 Q80 -3 205 8 Q381 -2 390 80 Q401 159 284 169 L94 179 L68 203 L69 175 Q-6 166 8 91 Q8 46 25 25Z" fill="url(#paper)" stroke="#a86d37" stroke-width="3"/><path d="M25 31 Q80 5 200 15 Q378 4 382 81" fill="none" stroke="#fff4d6" stroke-width="3"/><g fill="#c58364" opacity=".8"><ellipse cx="349" cy="39" rx="6" ry="13"/><ellipse cx="349" cy="39" rx="6" ry="13" transform="rotate(60 349 39)"/><ellipse cx="349" cy="39" rx="6" ry="13" transform="rotate(120 349 39)"/></g>')
svg('mode_book.svg',120,90,'<path d="M11 17 L54 10 L62 18 L105 13 L112 72 L66 82 L58 77 L8 82Z" fill="#af5a26" stroke="#7b421e" stroke-width="3"/><path d="M14 14 Q37 4 60 16 Q81 5 104 12 L103 66 Q79 59 62 75 Q36 64 13 74Z" fill="#fff0c0" stroke="#c2853b" stroke-width="3"/><path d="M60 17 L62 73 M22 23 L49 20 M22 34 L49 31 M22 45 L49 42 M73 22 L96 20 M73 33 L96 30 M73 44 L96 41" fill="none" stroke="#b98b50" stroke-width="2"/><path d="M95 68 L112 25 L116 28 L100 71 L93 76Z" fill="#eab851" stroke="#8a521e" stroke-width="2"/>')
svg('mode_review.svg',120,90,'<rect x="16" y="20" width="68" height="54" rx="5" fill="#d6ac75" stroke="#8b4f24" stroke-width="3" transform="rotate(-12 16 20)"/><rect x="41" y="12" width="66" height="59" rx="6" fill="#fff0c5" stroke="#ad6931" stroke-width="3" transform="rotate(10 41 12)"/><path d="M87 35 A18 18 0 1 0 86 59 M86 35 L88 23 M86 35 L73 34 M59 58 A18 18 0 0 0 88 56" fill="none" stroke="#a66d32" stroke-width="5"/>')
svg('mode_dictionary.svg',120,90,'<path d="M24 8 L93 13 L101 78 L29 83 L15 72Z" fill="#633129" stroke="#c18b3a" stroke-width="3"/><path d="M33 13 L90 18 L96 70 L36 75Z" fill="#9c4031" stroke="#edc46b" stroke-width="2"/><path d="M21 67 L89 63 L96 70 L28 77Z" fill="#f4dca4" stroke="#8e562a" stroke-width="2"/><path d="M40 27 L79 27 M42 54 L83 54 M52 38 L69 38 M60 34 L60 44" fill="none" stroke="#e9bf68" stroke-width="3"/>')
import random
rng=random.Random(1404)
for state, stroke, fill in [('idle','#eee4c7','#25463b'),('hover','#ffe9ac','#355a42'),('correct','#d5f59a','#426c38'),('wrong','#f1b1a2','#75463d'),('disabled','#aab49a','#29453b')]:
    marks=[]
    for i in range(80):
        x=rng.uniform(24,455)
        y=rng.choice([8,87])+rng.uniform(-1.3,1.3)
        marks.append(f'<path d="M{x:.1f} {y:.1f} l{rng.uniform(1,4):.1f} {rng.uniform(-.5,.5):.1f}" stroke="{stroke}" stroke-width="1" opacity=".4"/>')
    svg('answer_'+state+'.svg',480,100,f'<rect x="6" y="6" width="468" height="86" rx="22" fill="{fill}" opacity=".72"/><rect x="7" y="7" width="465" height="82" rx="21" fill="none" stroke="{stroke}" stroke-width="3.3"/><rect x="10" y="10" width="459" height="76" rx="19" fill="none" stroke="{stroke}" stroke-width="1" opacity=".55"/>'+''.join(marks))
marks=[]
for i in range(220):
    y=rng.uniform(13,119)
    start=rng.uniform(10,80)
    end=rng.uniform(601,672)
    marks.append(f'<path d="M{start:.1f} {y:.1f} L{end:.1f} {y+rng.uniform(-4,4):.1f}" stroke="#fff0cc" stroke-width="{rng.uniform(.4,1.4):.1f}" opacity="{rng.uniform(.1,.35):.2f}"/>')
svg('chalk_prompt_swipe.svg',680,135,'<path d="M35 14 L635 12 L666 27 L651 51 L671 100 L639 117 L34 119 L8 99 L23 75 L12 51Z" fill="#f0e3c3" opacity=".85"/>'+''.join(marks))
print('Built 15 original decorative SVG assets')

# Compact mobile controls use their own proportions rather than stretched PC pills.
for name, fill in [('portrait_pill.svg','paper'),('portrait_count_green.svg','green')]:
    svg(name,300,110,defs+f'<rect x="5" y="9" width="290" height="96" rx="44" fill="#683b1e" opacity=".35"/><rect x="4" y="3" width="292" height="98" rx="45" fill="url(#gold)" stroke="#774422" stroke-width="2"/><rect x="10" y="9" width="280" height="86" rx="39" fill="url(#{fill})" stroke="#fff2d1" stroke-width="3"/><rect x="16" y="15" width="268" height="74" rx="33" fill="none" stroke="#c38c4e" stroke-width="1.5"/>')

# Portrait-only visual components, keeping existing landscape vectors intact.
for name, fill in [('portrait_card_paper.svg','paper'),('portrait_card_green.svg','green')]:
    svg(name,800,170,defs+f'<rect x="5" y="9" width="790" height="157" rx="30" fill="#61371b" opacity=".3"/><rect x="4" y="4" width="792" height="155" rx="30" fill="url(#gold)" stroke="#fff0bd" stroke-width="3"/><rect x="12" y="12" width="776" height="139" rx="25" fill="url(#{fill})" stroke="#b37c44" stroke-width="2"/><rect x="20" y="20" width="760" height="123" rx="20" fill="none" stroke="#edc48a" stroke-width="1.5"/><g fill="none" stroke="#cc9a60" stroke-width="3"><path d="M27 49 Q53 28 72 36 M32 65 Q47 48 53 44 M773 49 Q747 28 728 36 M768 65 Q753 48 747 44 M27 118 Q53 139 72 131 M773 118 Q747 139 728 131"/></g>')
svg('portrait_type_banner.svg',600,110,'<path d="M36 26 Q300 -5 564 26 L556 77 Q300 52 44 78Z" fill="#284536" fill-opacity=".65" stroke="#e8e4ca" stroke-width="3"/><path d="M22 49 L2 40 L9 79 L43 71 M578 49 L598 40 L591 79 L557 71" fill="none" stroke="#e8e4ca" stroke-width="3"/>')
portrait=root=Path(__file__).resolve().parents[2]/'assets/school/portrait'
portrait.mkdir(parents=True,exist_ok=True)
(portrait/'chalk_underline.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="400" height="30" viewBox="0 0 400 30"><path d="M14 19 Q188 0 386 16" fill="none" stroke="#e8c449" stroke-width="7"/><path d="M32 27 Q207 12 365 25" fill="none" stroke="#e8c449" stroke-width="2" opacity=".7"/></svg>',encoding='utf-8')
